// @ts-check
import { defineConfig } from "astro/config";
import sitemap from "@astrojs/sitemap";
import tailwindcss from "@tailwindcss/vite";
import fs from "node:fs";

// Old URLs that must keep working (generated by scripts/migrate/wp-to-content.mjs).
const allRedirects = JSON.parse(fs.readFileSync(new URL("./src/data/redirects.json", import.meta.url), "utf8"));
// Redirects to files (feed.xml) are handled by the host configs (public/_redirects, vercel.json) only.
const redirects = Object.fromEntries(Object.entries(allRedirects).filter(([, to]) => !/\.[a-z]+$/i.test(to)));

export default defineConfig({
  site: "https://swaanelauwaert.com",
  trailingSlash: "always",
  compressHTML: true,
  redirects,
  i18n: {
    locales: ["en", "nl", "fr"],
    defaultLocale: "en",
    routing: { prefixDefaultLocale: true, redirectToDefaultLocale: false },
  },
  integrations: [sitemap({ filter: (page) => !page.includes("/404/") })],
  vite: { plugins: [tailwindcss()] },
});
